META = dict(nama="Aviation", jp="航空", emoji="✈️", co="空港・航空会社")
SPEC = dict(kerja="安全と、時間の正確さをとても大切にしている", kerja_id="sangat mengutamakan keselamatan dan ketepatan waktu", soal={
 "shibou-01": ("なぜ航空の仕事を選びましたか。", "Mengapa Anda memilih pekerjaan di bidang penerbangan?", "小さいころから、飛行機が好きでした。空港で、たくさんの人が安全に旅行できるように、支える仕事がしたいです。", "Sejak kecil saya suka pesawat. Saya ingin bekerja di bandara menopang agar banyak orang bisa bepergian dengan aman.", [("航空", "penerbangan"), ("空港", "bandara"), ("飛行機", "pesawat"), ("支える", "menopang")]),
 "shibou-02": ("なぜ日本で航空の仕事を学びたいですか。", "Mengapa Anda ingin belajar pekerjaan penerbangan di Jepang?", "日本の空港は、安全と、時間の正確さを、とても大切にしていると聞きました。その考え方を学びたいです。", "Saya dengar bandara Jepang sangat mengutamakan keselamatan dan ketepatan waktu. Saya ingin mempelajari cara berpikir itu.", [("安全", "keselamatan"), ("正確", "tepat"), ("考え方", "cara berpikir")]),
 "shibou-04": ("この仕事に興味を持った理由は何ですか。", "Apa alasan Anda tertarik pada pekerjaan ini?", "飛行機が、時間どおりに安全に飛ぶために、たくさんの人が働いています。その一人になって、役に立ちたいです。", "Banyak orang bekerja agar pesawat terbang aman dan tepat waktu. Saya ingin menjadi salah satunya dan berguna.", [("飛ぶ", "terbang"), ("役に立つ", "berguna"), ("興味", "minat")]),
 "shibou-05": ("航空の仕事で、一番楽しみなことは何ですか。", "Apa yang paling Anda nantikan dari pekerjaan penerbangan?", "自分が働いた飛行機が、無事に飛んでいくのを見ることです。日本の安全管理も学びたいです。", "Melihat pesawat yang saya tangani lepas landas dengan selamat. Saya juga ingin belajar manajemen keselamatan Jepang.", [("無事に", "dengan selamat"), ("安全管理", "manajemen keselamatan"), ("楽しみ", "dinantikan")]),
 "shigoto-01": ("空港の地上の仕事、または航空機整備の主な仕事は何だと思いますか。", "Menurut Anda, apa pekerjaan utama ground handling bandara atau perawatan pesawat?", "荷物を運んだり、飛行機を誘導したり、点検して直したりする仕事だと思います。どれも安全に関わる仕事です。", "Saya kira pekerjaannya mengangkut bagasi, memandu pesawat, serta memeriksa dan memperbaikinya. Semuanya menyangkut keselamatan.", [("手荷物", "bagasi"), ("誘導", "pemanduan"), ("点検", "inspeksi")]),
 "shigoto-02": ("朝早くや、夜遅くに働くことはできますか。", "Bisakah Anda bekerja pagi buta atau larut malam?", "はい、できます。空港は、早朝や夜にも仕事があると聞きました。体調をしっかり整えます。", "Ya, bisa. Saya dengar bandara punya pekerjaan juga di pagi buta dan malam. Saya akan menjaga kondisi badan dengan baik.", [("早朝", "pagi buta"), ("夜間", "malam hari"), ("体調", "kondisi badan")]),
 "shigoto-03": ("暑い日や寒い日や雨の日でも、外で働けますか。", "Bisakah Anda bekerja di luar walau panas, dingin, atau hujan?", "はい、大丈夫です。暑い日はこまめに水を飲んで、寒い日は服をたくさん着ます。雨の日は、すべらないよう気をつけます。", "Ya, tidak masalah. Saat panas saya sering minum air, saat dingin memakai banyak lapis pakaian. Saat hujan saya berhati-hati agar tidak terpeleset.", [("暑い", "panas"), ("寒い", "dingin"), ("すべる", "terpeleset")]),
 "shigoto-04": ("飛行機の音や、エンジンの音がある環境でも大丈夫ですか。", "Apakah Anda baik-baik saja di lingkungan dengan suara pesawat dan mesin?", "はい、大丈夫です。必要なときは、耳を守る道具を使います。まわりの合図も、よく見て、聞きます。", "Ya, tidak masalah. Bila perlu saya memakai alat pelindung telinga. Saya juga memperhatikan isyarat sekitar dengan baik.", [("エンジン", "mesin"), ("騒音", "kebisingan"), ("合図", "isyarat")]),
 "shigoto-05": ("重い荷物を運ぶ体力はありますか。", "Apakah Anda punya stamina untuk mengangkat barang berat?", "はい、あります。毎日運動をして、体力をつけています。重い荷物は、腰に気をつけて持ちます。", "Ya, ada. Saya berolahraga setiap hari. Barang berat saya angkat dengan menjaga pinggang.", [("体力", "stamina"), ("重い", "berat"), ("腰", "pinggang")]),
 "shigoto-06": ("飛行機が遅れたときなど、予定が変わって、残業があっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan lembur bila rencana berubah, misalnya pesawat terlambat?", "はい、大丈夫です。予定が変わったときは、責任者の指示に従います。ただ、決められた休けいは、必ず取ります。", "Ya, tidak masalah. Saat rencana berubah saya mengikuti instruksi penanggung jawab. Namun saya pasti mengambil istirahat yang ditentukan.", [("遅れ", "keterlambatan"), ("残業", "lembur"), ("指示", "instruksi")]),
 "shigoto-07": ("空港で、車や、機械を使うとき、何に気をつけますか。", "Apa yang Anda perhatikan saat memakai kendaraan dan mesin di bandara?", "決められた速さと、ルールを守ります。まわりに人や飛行機がいないか、よく見ます。使い方が分からないときは、使いません。", "Saya mematuhi kecepatan dan aturan yang ditentukan. Saya memeriksa apakah ada orang atau pesawat di sekitar. Kalau tidak tahu cara pakainya, saya tidak memakainya.", [("ルール", "aturan"), ("確認", "memastikan"), ("速さ", "kecepatan")]),
 "shigoto-08": ("英語や、日本語で、指示を聞いて、仕事することはできますか。", "Apakah Anda bisa bekerja sambil mendengar instruksi dalam bahasa Inggris atau Jepang?", "はい、少しできます。分からないときは、必ず聞き返します。まだ勉強中ですが、がんばります。", "Ya, sedikit bisa. Kalau tidak paham, saya pasti bertanya ulang. Saya masih belajar, tetapi akan berusaha.", [("聞き返す", "bertanya ulang"), ("指示", "instruksi"), ("勉強中", "sedang belajar")]),
 "shigoto-09": ("航空の仕事で、大切なことは何だと思いますか。", "Menurut Anda, apa yang penting dalam pekerjaan penerbangan?", "安全と、確認を忘れないことだと思います。小さい間違いが、大きい事故につながることがあります。", "Menurut saya, keselamatan dan tidak lupa memeriksa. Kesalahan kecil bisa menyebabkan kecelakaan besar.", [("安全", "keselamatan"), ("確認", "pengecekan"), ("事故", "kecelakaan")]),
 "shigoto-10": ("飛行機が空港に着いてから、また飛ぶまで、どんな作業がありますか。", "Pekerjaan apa saja sejak pesawat mendarat sampai terbang lagi?", "荷物を降ろして、点検して、荷物を積みます。お客様が乗ったら、出発の準備をします。", "Menurunkan bagasi, memeriksa pesawat, lalu memuat bagasi. Setelah penumpang naik, bersiap untuk berangkat.", [("積み下ろし", "bongkar muat"), ("点検", "inspeksi"), ("出発", "keberangkatan")]),
 "shigoto-11": ("お客様の荷物や、貨物を扱うとき、何に気をつけますか。", "Apa yang Anda perhatikan saat menangani bagasi dan kargo penumpang?", "荷物を、ていねいに扱います。名前の札や、行き先を、間違えないように確認します。", "Saya menangani bagasi dengan hati-hati. Saya memeriksa label nama dan tujuan agar tidak keliru.", [("行き先", "tujuan"), ("札", "label"), ("確認", "memastikan")]),
 "shigoto-12": ("チェックリストを見て、作業することはできますか。", "Apakah Anda bisa bekerja sambil melihat daftar periksa?", "はい、できます。一つずつ、順番に確認します。確認したら、チェックを入れて、記録します。", "Ya, bisa. Saya memeriksa satu per satu secara berurutan. Setelah diperiksa, saya menandai dan mencatat.", [("チェックリスト", "daftar periksa"), ("順番", "urutan"), ("記録", "pencatatan")]),
 "shigoto-13": ("決まった時間までに、作業を終わらせることは、大切だと思いますか。", "Apakah menurut Anda menyelesaikan pekerjaan dalam waktu yang ditentukan itu penting?", "はい、大切だと思います。時間に遅れると、お客様や、ほかの飛行機に、影響が出るからです。でも、安全より急ぐことはしません。", "Ya, saya kira penting. Karena keterlambatan memengaruhi penumpang dan pesawat lain. Namun saya tidak akan terburu-buru melebihi keselamatan.", [("時間を守る", "tepat waktu"), ("影響", "dampak"), ("安全", "keselamatan")]),
 "taiou-02": ("荷物や、部品を、間違えてしまったら、どうしますか。", "Apa yang Anda lakukan kalau keliru bagasi atau suku cadang?", "すぐに正直に責任者に報告します。どうして間違えたか考えて、次は、確認を一回多くします。", "Saya segera melapor jujur kepada penanggung jawab. Saya memikirkan penyebabnya dan lain kali menambah satu kali pengecekan.", [("間違える", "keliru"), ("報告", "melapor"), ("確認", "pengecekan")]),
 "taiou-06": ("天気が悪くなって、飛行機の予定が急に変わったら、どうしますか。", "Apa yang Anda lakukan kalau cuaca memburuk dan jadwal pesawat berubah mendadak?", "責任者の指示をよく聞いて、安全を第一に動きます。分からないときは、すぐに聞きます。", "Saya mendengarkan instruksi penanggung jawab dan bergerak dengan mengutamakan keselamatan. Kalau tidak paham, saya langsung bertanya.", [("急に", "mendadak"), ("指示", "instruksi"), ("安全第一", "keselamatan utama")]),
 "taiou-08": ("お客様に、道や場所を聞かれたら、どうしますか。", "Apa yang Anda lakukan kalau pelanggan bertanya jalan atau lokasi?", "ていねいに、分かる範囲で、答えます。分からないときは、「確認します」と言って、ほかの人に聞きます。", "Saya menjawab dengan sopan sejauh yang saya tahu. Kalau tidak tahu, saya bilang \"Saya cek dulu\" dan bertanya kepada orang lain.", [("案内", "memandu"), ("確認する", "memeriksa"), ("ていねい", "sopan")]),
 "taiou-11": ("忙しい時期で、疲れているとき、どう気持ちを保ちますか。", "Bagaimana Anda menjaga semangat saat sibuk dan lelah?", "忙しい時期は短いと理解しています。しっかり寝て、食事をとって、体調を保ちます。", "Saya paham musim sibuk itu singkat. Saya tidur cukup, makan baik, dan menjaga kondisi badan.", [("疲れる", "lelah"), ("体調", "kondisi badan"), ("睡眠", "tidur")]),
 "taiou-12": ("先輩が専門用語や、略語で話して、分からないとき、どうしますか。", "Apa yang Anda lakukan kalau senior memakai istilah teknis atau singkatan yang tidak Anda pahami?", "「すみません、この言葉の意味を教えてください」と聞きます。メモして、あとで復習します。", "Saya bertanya \"Maaf, tolong jelaskan arti kata ini\". Saya mencatatnya dan mengulang pelajaran nanti.", [("専門用語", "istilah teknis"), ("意味", "arti"), ("復習", "mengulang pelajaran")]),
 "tim-01": ("飛行機が着いたとき、チームの人と、どのように作業を分けますか。", "Saat pesawat tiba, bagaimana Anda membagi tugas dengan tim?", "責任者の指示で、荷物を降ろす人、運ぶ人、点検する人などに分かれます。声をかけ合って、安全に作業します。", "Sesuai instruksi penanggung jawab, ada yang menurunkan, mengangkut, dan memeriksa. Kami saling memberi aba-aba agar aman.", [("分担", "pembagian tugas"), ("声をかけ合う", "saling memberi aba-aba"), ("責任者", "penanggung jawab")]),
 "tim-02": ("先輩の指示が分からなかったとき、どうしますか。", "Apa yang Anda lakukan kalau tidak paham instruksi senior?", "すぐに「もう一度お願いします」と聞きます。分からないまま作業すると、事故につながるからです。", "Saya segera meminta \"Tolong ulangi\". Bekerja tanpa paham bisa menyebabkan kecelakaan.", [("指示", "instruksi"), ("事故", "kecelakaan"), ("確認", "memastikan")]),
 "tim-03": ("いろいろな会社や、国の人と、どのようにコミュニケーションをとりますか。", "Bagaimana Anda berkomunikasi dengan berbagai perusahaan dan orang dari banyak negara?", "短く、はっきり話します。分かったときは「はい」と返事をして、分からないときは、もう一度聞きます。", "Saya berbicara singkat dan jelas. Saat paham saya menjawab \"Ya\", saat tidak paham saya bertanya lagi.", [("はっきり", "dengan jelas"), ("返事", "jawaban"), ("聞き返す", "bertanya ulang")]),
 "tim-04": ("会社の仲間と、どのように仲良くなりたいですか。", "Bagaimana Anda ingin akrab dengan rekan di perusahaan?", "毎日、元気にあいさつをします。教えてもらったときは、「ありがとうございます」と言います。", "Setiap hari saya menyapa dengan semangat. Saat diajari, saya mengatakan \"Terima kasih\".", [("あいさつ", "salam"), ("仲間", "rekan"), ("仲良くなる", "menjadi akrab")]),
 "anzen-01": ("空港の、飛行機の近くで、必ず身につけるものは何ですか。", "Apa yang wajib dikenakan di dekat pesawat di bandara?", "ヘルメット、安全靴、反射する安全ベスト、耳を守る道具を必ず着けます。", "Saya wajib memakai helm, sepatu keselamatan, rompi keselamatan reflektif, dan pelindung telinga.", [("安全ベスト", "rompi keselamatan"), ("ヘルメット", "helm"), ("耳せん", "penyumbat telinga")]),
 "anzen-02": ("エンジンが動いているとき、飛行機の近くで、どうしますか。", "Apa yang Anda lakukan di dekat pesawat saat mesin menyala?", "決められた場所と、決められた道だけを通ります。エンジンの前や、後ろには、絶対に近づきません。", "Saya hanya lewat di tempat dan jalur yang ditentukan. Saya sama sekali tidak mendekati bagian depan atau belakang mesin.", [("エンジン", "mesin"), ("吸い込まれる", "terhisap"), ("近づく", "mendekat")]),
 "anzen-03": ("異物が落ちているのを見つけたら、どうしますか。", "Apa yang Anda lakukan kalau menemukan benda asing di landasan atau area kerja?", "そのままにしないで、すぐに拾うか、責任者に知らせます。小さいものも、飛行機の事故につながるからです。", "Saya tidak membiarkannya, segera memungut atau melapor kepada penanggung jawab. Benda kecil pun bisa menyebabkan kecelakaan pesawat.", [("異物", "benda asing"), ("拾う", "memungut"), ("事故", "kecelakaan")]),
 "anzen-04": ("重い荷物を運ぶとき、どうしますか。", "Apa yang Anda lakukan saat mengangkat barang berat?", "一人で持てないときは、ほかの人に頼みます。腰を曲げないで、ひざを使って持ち上げます。", "Kalau tidak sanggup sendiri, saya minta bantuan orang lain. Saya mengangkat dengan menekuk lutut, bukan membungkuk dari pinggang.", [("腰", "pinggang"), ("ひざ", "lutut"), ("頼む", "meminta bantuan")]),
 "seikatsu-07": ("空港の近くの町での生活に、不便なことがあっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan ketidaknyamanan hidup di kota dekat bandara?", "大丈夫です。寮から空港までの行き方を、調べておきます。休みの日は、買い物や勉強をします。", "Tidak masalah. Saya akan mengecek rute dari asrama ke bandara. Saat libur saya berbelanja dan belajar.", [("寮", "asrama"), ("行き方", "rute"), ("調べる", "mengecek")]),
 "seikatsu-08": ("日本の空港や、飛行機について、知っていることはありますか。", "Apa yang Anda ketahui tentang bandara dan pesawat di Jepang?", "日本の飛行機は、時間がとても正確だと聞きました。空港が、とてもきれいで、案内も分かりやすいと知っています。", "Saya dengar pesawat di Jepang sangat tepat waktu. Saya tahu bandaranya sangat bersih dan petunjuknya mudah dipahami.", [("正確", "tepat"), ("案内", "petunjuk"), ("きれい", "bersih")]),
 "mokuhyou-05": ("日本で航空の仕事を学んだあと、自分の国でどんなことをしたいですか。", "Setelah belajar pekerjaan penerbangan di Jepang, apa yang ingin Anda lakukan di negara sendiri?", "日本で学んだ安全の考え方と、確認の習慣を使って、自分の国の空港や、航空会社で、働きたいです。", "Saya ingin bekerja di bandara atau maskapai negara saya dengan memakai cara berpikir keselamatan dan kebiasaan memeriksa yang saya pelajari di Jepang.", [("安全", "keselamatan"), ("習慣", "kebiasaan"), ("航空会社", "maskapai")]),
})
